#!/usr/bin/env bash
# DNS lab self-extract installer
set -euo pipefail
TARGET="${1:-$PWD/dns-lab}"
echo "[*] install to: $TARGET"
mkdir -p "$TARGET"
PAYLOAD="$(mktemp /tmp/dns-lab-payload.XXXXXX.tar.gz)"
trap 'rm -f "$PAYLOAD"' EXIT
base64 -d > "$PAYLOAD" <<'PAYLOAD_B64'

PAYLOAD_B64
tar xzf "$PAYLOAD" -C "$TARGET" --strip-components=1
echo "[+] done: $TARGET"
echo '    cd there && sudo ./lab.sh deps'
